using System;
using System.Collections;
using FMODUnity;
using LittleLeo;
using UnityEngine;

namespace Astrea;

public class DiceRolling : MonoBehaviour
{
	[Header("Rolling Dice")]
	[SerializeField]
	private float force;

	[SerializeField]
	private Vector3 dirMinTorque;

	[SerializeField]
	private Vector3 dirMaxTorque;

	[SerializeField]
	private float zForceMultiplier;

	[SerializeField]
	private float stopingDiceRollingRange;

	[SerializeField]
	private float diceNotReachingStoppingDiceRollingRangeFallbackDuration;

	[Header("Trail")]
	[SerializeField]
	private GameObject diceRolledVFXPrefab;

	[Header("Components")]
	[SerializeField]
	private DiceFaceInstance3D[] diceFaceInstances;

	[SerializeField]
	private Rigidbody rb;

	[SerializeField]
	private MeshCollider meshCollider;

	[SerializeField]
	private DiceInstance diceInstance;

	[SerializeField]
	private DiceVisuals diceVisuals;

	[Header("SFX")]
	[SerializeField]
	private EventReference uiDiceRollShine;

	[SerializeField]
	private EventReference uiDiceRollSingle;

	private Coroutine diceRollingSFXDelayCoroutine;

	private float diceNotReachingStoppingDiceRollingRangeFallbackTimer;

	private Dice dice => diceInstance.Dice;

	public void SetupDiceToRoll()
	{
		meshCollider.sharedMesh = dice.DiceTier.DiceMesh;
		rb.useGravity = false;
		rb.isKinematic = false;
		rb.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
		meshCollider.enabled = false;
	}

	public void RollDice(bool stastOfTurnHandDiceRolling)
	{
		diceInstance.SetDiceState(DiceState.Rolling);
		diceVisuals.OnRollDice();
		ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CheckIfStopedRolling(stastOfTurnHandDiceRolling));
		rb.transform.eulerAngles = new Vector3(RandomUtilities.RandomInt(-360, 360), RandomUtilities.RandomInt(-360, 360), RandomUtilities.RandomInt(-360, 360));
		rb.useGravity = true;
		meshCollider.enabled = true;
		float x = RandomUtilities.RandomFloatWithSeed(dirMinTorque.x, dirMaxTorque.x);
		float y = RandomUtilities.RandomFloatWithSeed(dirMinTorque.y, dirMaxTorque.y);
		float z = RandomUtilities.RandomFloatWithSeed(dirMinTorque.z, dirMaxTorque.z);
		rb.AddTorque(x, y, z);
		rb.AddForce(GetPointOnCirclePerimeter(base.transform.position, 100f, RandomUtilities.RandomInt(0, 360)) * force, ForceMode.Impulse);
	}

	private Vector3 GetPointOnCirclePerimeter(Vector3 center, float radius, int angle)
	{
		Vector3 result = default(Vector3);
		result.x = center.x + radius * Mathf.Sin((float)angle * (MathF.PI / 180f));
		result.y = center.y + radius * Mathf.Cos((float)angle * (MathF.PI / 180f));
		result.z = zForceMultiplier;
		return result;
	}

	private IEnumerator CheckIfStopedRolling(bool stastOfTurnHandDiceRolling)
	{
		diceNotReachingStoppingDiceRollingRangeFallbackTimer = 0f;
		yield return new WaitForSeconds(0.5f);
		while (rb.velocity.magnitude > stopingDiceRollingRange)
		{
			diceNotReachingStoppingDiceRollingRangeFallbackTimer += Time.deltaTime;
			bool flag = false;
			if (diceNotReachingStoppingDiceRollingRangeFallbackTimer >= diceNotReachingStoppingDiceRollingRangeFallbackDuration)
			{
				rb.velocity = Vector3.zero;
				rb.angularVelocity = Vector3.zero;
				flag = true;
			}
			if (base.transform.position.z >= 2f || base.transform.position.z <= -6f || base.transform.position.x >= 11.5f || base.transform.position.x <= -11.5f || base.transform.position.y >= 7.5f || base.transform.position.y <= -7.5f)
			{
				base.transform.position = Vector3.back * 2f;
			}
			if (flag)
			{
				break;
			}
			yield return InvokeAlternatives.WaitOneFrame();
		}
		int rolledDiceFaceIndex = GetRolledDiceFaceIndex();
		StopedRollingVFX(rolledDiceFaceIndex);
		StopedRollingSetRB();
		yield return new WaitForSeconds(0.2f);
		StopedRolling(rolledDiceFaceIndex, stastOfTurnHandDiceRolling);
	}

	private int GetRolledDiceFaceIndex()
	{
		int result = 0;
		float num = 1000f;
		for (int i = 0; i < diceFaceInstances.Length; i++)
		{
			if (diceFaceInstances[i].transform.position.z < num)
			{
				num = diceFaceInstances[i].transform.position.z;
				result = i;
			}
		}
		return result;
	}

	private void StopedRollingVFX(int rolledDiceFaceIndex)
	{
		float num = -1000f;
		Vector3 position = Vector3.zero;
		for (int i = 0; i < diceFaceInstances.Length; i++)
		{
			if (diceFaceInstances[i].transform.position.z > num)
			{
				num = diceFaceInstances[i].transform.position.z;
				position = diceFaceInstances[i].transform.position;
			}
		}
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(diceRolledVFXPrefab.name, 1f);
		@object.transform.position = position;
		ParticleSystem.MainModule main = @object.GetComponent<ParticleSystem>().main;
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDiceRollShine);
		BaseBattleActionData baseBattleActionData = dice.GetDiceFaces()[rolledDiceFaceIndex].BattleAction.BaseBattleActionData;
		if (baseBattleActionData.EnableColorReference)
		{
			main.startColor = baseBattleActionData.colorReference.Value;
		}
		else
		{
			main.startColor = baseBattleActionData.ActionColor;
		}
	}

	private void StopedRollingSetRB()
	{
		rb.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
		rb.isKinematic = true;
	}

	private void StopedRolling(int rolledDiceFaceIndex, bool stastOfTurnHandDiceRolling)
	{
		diceVisuals.StoreDiceTrailParticles();
		diceInstance.UpdateRolledActionFace(rolledDiceFaceIndex);
		ReferenceSingleton<DiceRollingHandler>.Instance.OnRollingDiceEnded(stastOfTurnHandDiceRolling);
	}

	private void OnCollisionEnter(Collision other)
	{
		if (diceRollingSFXDelayCoroutine == null)
		{
			diceRollingSFXDelayCoroutine = StartCoroutine(SFXDelay());
		}
	}

	private IEnumerator SFXDelay()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(uiDiceRollSingle);
		yield return new WaitForSeconds(0.2f);
		diceRollingSFXDelayCoroutine = null;
	}
}
